record.field:
icp = env['ir.config_parameter'].sudo()
action = {
    'type': 'ir.actions.act_window_close',
    'params': {
        'database_uuid': icp.get_param('database.uuid') or '',
        'base_url': (icp.get_param('spoki.base_url') or 'https://api.spoki.com').rstrip('/'),
        'app_url': (icp.get_param('spoki.app_url') or 'https://app.spoki.com').rstrip('/'),
        'signing_key': icp.get_param('spoki.signing_key') or '',
        'user_email': env.user.email or '',
    },
}

key = (env.context.get('spoki_signing_key') or '').strip().lower()
base_url = (env.context.get('spoki_base_url') or '').strip().rstrip('/')
if key and (len(key) != 64 or not set(key) <= set('0123456789abcdef')):
    raise UserError('Spoki sent an invalid signing key. Please try connecting again.')
local_prefixes = ('http://localhost:', 'http://127.0.0.1:')
if base_url and not (base_url.startswith('https://') or base_url.startswith(local_prefixes)):
    raise UserError('Spoki sent an invalid address. Please try connecting again.')
icp = env['ir.config_parameter'].sudo()
icp.set_param('spoki.signing_key', key or False)
if key and base_url:
    icp.set_param('spoki.base_url', base_url)
action = {'type': 'ir.actions.act_window_close', 'params': {'connected': bool(key)}}
